#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
server=dfs-poc-jd-20260930
client=dfs-poc-client-jd-20260930
bash scripts/cloud-command.sh "$server" 'cd ~/x/jd/dfs && python3 scripts/collect-run.py runtime/data/colocated-final results/colocated-final && python3 scripts/collect-run.py runtime/data/network results/server-final && python3 scripts/collect-run.py runtime/data/large-tenant results/large-final && python3 scripts/collect-run.py "$(cat results/latest-smoke.txt)" results/smoke-final && python3 scripts/collect-run.py "$(cat results/latest-policy.txt)" results/policy-final && python3 scripts/collect-run.py "$(cat results/latest-failures.txt)" results/failures-final && sudo journalctl -u dfsd-poc --no-pager > results/server-final/systemd-journal.txt && cp runtime/data/network/db/LOG results/server-final/rocksdb-after-recovery.log && ls -l runtime/data/network/db > results/server-final/storage-files.txt && du -sb runtime/data/network/db > results/server-final/storage-after-recovery.txt && lscpu > results/server-final/cpu.txt && lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINTS > results/server-final/disks.txt && dpkg-query -W > results/server-final/packages.txt && free -b > results/server-final/memory.txt && ~/.cargo/bin/rustc -Vv > results/server-final/rustc.txt && sha256sum target/release/dfsd target/release/dfs-mount target/release/dfsctl target/release/dfs-load target/release/dfs-recovery > results/server-final/binaries.sha256 && python3 scripts/fingerprint.py > results/server-final/source-manifest.json && tar -czf runtime/final-export.tar.gz results/colocated-final results/server-final results/large-final results/smoke-final results/policy-final results/failures-final results/network-prepare.log results/recovery-prefix.json results/recovery-boundaries.json results/systemd-install.log'
gcloud compute scp "dfs@$server:~/x/jd/dfs/runtime/final-export.tar.gz" cloud/final-export.tar.gz --project=dust-dev --zone=us-central1-a --plain --scp-flag=-icloud/ssh-key --scp-flag=-oUserKnownHostsFile=cloud/known_hosts
tar -xzf cloud/final-export.tar.gz
bash scripts/cloud-command.sh "$client" 'cd ~/x/jd/dfs && python3 scripts/collect-run.py runtime/network results/network-final && dpkg-query -W > results/network-final/packages.txt && lscpu > results/network-final/cpu.txt && sha256sum target/release/dfs-mount target/release/dfs-load target/release/dfs-recovery > results/network-final/binaries.sha256 && tar -czf runtime/network-export.tar.gz results/network-final results/network-experiment.log results/power-client.log'
gcloud compute scp "dfs@$client:~/x/jd/dfs/runtime/network-export.tar.gz" cloud/network-export.tar.gz --project=dust-dev --zone=us-central1-a --plain --scp-flag=-icloud/ssh-key --scp-flag=-oUserKnownHostsFile=cloud/known_hosts
tar -xzf cloud/network-export.tar.gz
python3 scripts/summarize-results.py > results/summary.json
